#include <zephyr/kernel.h>
#include <zephyr/sys/notify.h>

int sys_notify_validate(struct sys_notify *notify)
{
	if (notify == NULL) {
		return -EINVAL;
	}

	/* Clear the unvalidated bits */
	uint32_t method = notify->flags & SYS_NOTIFY_METHOD_MASK;

	/* Verify valid method and arguments, and drop everything but the
	 * method.
	 */
	switch (method) {
	case SYS_NOTIFY_METHOD_COMPLETED:
		break;
	case SYS_NOTIFY_METHOD_CALLBACK:
		if (notify->method.callback == NULL) {
			return -EINVAL;
		}
		break;
	case SYS_NOTIFY_METHOD_SIGNAL:
#ifdef CONFIG_POLL
		if (notify->method.signal == NULL) {
			return -EINVAL;
		}
		break;
#endif /* CONFIG_POLL */
	default:
		return -EINVAL;
	}

	notify->flags = method;
	notify->result = 0;

	return 0;
}

sys_notify_generic_callback sys_notify_finalize(struct sys_notify *notify,
						    int res)
{
	sys_notify_generic_callback rv = NULL;
	uint32_t method = sys_notify_get_method(notify);

	notify->result = res;
	switch (method) {
	case SYS_NOTIFY_METHOD_COMPLETED:
		break;
	case SYS_NOTIFY_METHOD_CALLBACK:
		rv = notify->method.callback;
		break;
#ifdef CONFIG_POLL
	case SYS_NOTIFY_METHOD_SIGNAL:
		k_poll_signal_raise(notify->method.signal, res);
		break;
#endif /* CONFIG_POLL */
	default:
		__ASSERT_NO_MSG(false);
	}
	compiler_barrier();
	notify->flags |= SYS_NOTIFY_EXTENSION_POS ? BIT(SYS_NOTIFY_EXTENSION_POS - 1) : 0;

	return rv;
}
